    if quiet:
        level = logging.ERROR
    elif verbose &gt;= 2:
        level = logging.DEBUG
    elif verbose == 1:
        level = logging.INFO
    else:
        level = logging.WARNING
    # force=True overrides any root config already installed at import time
    # (e.g. biosigio.core.emg calls basicConfig on import), so -v/-q actually apply
    # and CLI diagnostics reach stderr.
    logging.basicConfig(
        level=level, stream=sys.stderr, format="%(levelname)s: %(message)s", force=True
    )
